function imageForCategory(category: string): string {
  if (category === "แกงและซุป") return RECIPE_IMAGES.curry;
  if (category === "สุขภาพดี" || category === "สลัด") return RECIPE_IMAGES.tofu;
  return RECIPE_IMAGES.basil;
}

export function getRecipeImage(recipeId: string, category: string): string {
  return RECIPE_IMAGES_BY_ID[recipeId] ?? imageForCategory(category);
}

const extraRecipes: Recipe[] = extraRecipeSpecs.map((spec) => ({
  id: spec.id,
  title: spec.title,
  category: spec.category,
  time: spec.time,
  servings: spec.servings,
  imageUri: getRecipeImage(spec.id, spec.category),
  description: spec.description,
  isFavorite: false,
  ingredients: spec.ingredients.map(([name, quantity, unit, category], index) => ({ id: `${spec.id}-ingredient-${index + 1}`, name, quantity, unit, category })),
  steps: [`เตรียมวัตถุดิบสำหรับ${spec.title}ให้พร้อม`, `ปรุงตามลำดับจนสุกหอมและได้รสชาติกลมกล่อม`, `จัดเสิร์ฟขณะร้อน หรือแบ่งเก็บเป็นมื้อถัดไป`],
}));

recipes.push(...extraRecipes);

export function createSeedData(): KruaData {
  return {
    recipes: recipes.map((recipe) => ({
      ...recipe,
      ingredients: recipe.ingredients.map((ingredient) => ({ ...ingredient })),
      steps: [...recipe.steps],
    })),
    plan: [
      { id: "plan-mon-lunch", dayKey: "mon", mealType: "มื้อกลางวัน", recipeId: "basil-chicken" },
      { id: "plan-wed-dinner", dayKey: "wed", mealType: "มื้อเย็น", recipeId: "green-curry" },
      { id: "plan-sat-lunch", dayKey: "sat", mealType: "มื้อกลางวัน", recipeId: "tofu-bowl" },
    ],
    shoppingItems: [
      { id: "shop-1", name: "นมโอ๊ต", quantity: 1, unit: "กล่อง", category: "ของแห้ง", checked: true, source: "manual" },
      { id: "shop-2", name: "ไข่ไก่", quantity: 6, unit: "ฟอง", category: "โปรตีน", checked: false, source: "manual" },
      { id: "shop-3", name: "กล้วย", quantity: 6, unit: "ลูก", category: "ผักและผลไม้", checked: false, source: "manual" },
    ],
    hasOnboarded: false,
    offlineMode: false,
    notificationsEnabled: false,
    notificationTime: "17:30",
    notificationPermission: "unknown",
    unitSystem: "เมตริก",
    lastSavedAt: new Date().toISOString(),
  };
}

export function formatQuantity(quantity: number): string {
  return Number.isInteger(quantity) ? String(quantity) : quantity.toFixed(1).replace(/\.0$/, "");
}
